{"status":"fulfilled","value":{"chunk_id":"4ab2f9","wall_time_seconds":0.000007166,"exit_code":0,"original_token_count":4665,"output":"     1	// Orchestration (Kaizen v0): a crude round-robin debate that accumulates into one
     2	// markdown transcript. No scholastic protocol / respondeo / eval yet — those are the
     3	// next small steps. This is the smallest thing that reproduces the manual workflow.
     4	
     5	import { mkdtemp, rm } from "node:fs/promises";
     6	import { tmpdir } from "node:os";
     7	import { join } from "node:path";
     8	import { execFile } from "node:child_process";
     9	import { promisify } from "node:util";
    10	import type { Participant, AgentResult } from "./adapters.ts";
    11	
    12	const execFileAsync = promisify(execFile);
    13	
    14	function log(msg: string) { console.error(`[disputatio] ${msg}`); }
    15	
    16	export type Turn = { title: string; participant: string; result: AgentResult };
    17	
    18	export type RespondeoStatus = "RESOLVED" | "NEEDS_INPUT" | "FAILED";
    19	
    20	export type DebateOutcome = {
    21	  transcript: string;       // the full markdown artifact (incl. cost footnotes, failure details)
    22	  turns: Turn[];            // per-turn results, raw CLI captures attached (diagnostics)
    23	  aborted?: string;         // set when the debate could not proceed (e.g. <2 proposals)
    24	  respondeo?: {             // the judge's consolidatio (only when a judge ran)
    25	    status: RespondeoStatus;
    26	    text: string;           // the verdict body — written verbatim to respondeo.md
    27	  };
    28	  finalReport?: {           // the redactio: the deliverable, only when respondeo RESOLVED
    29	    text: string;           // written verbatim to final-report.md
    30	  };
    31	  finalReportError?: {      // set when the redactio ran but failed (debate + verdict still succeeded)
    32	    budgetExhausted: boolean;
    33	    message: string;
    34	  };
    35	};
    36	
    37	// Transcript view (for the .md artifact): keeps cost + failure detail.
    38	function render(title: string, r: AgentResult): string {
    39	  if (r.ok) {
    40	    const cost = r.costUsd ? `\n\n_(cost: $${r.costUsd.toFixed(4)})_` : "";
    41	    return `## ${title}\n\n${r.text}${cost}\n`;
    42	  }
    43	  return `## ${title}\n\n> ⚠️ FAILED: ${r.error}\n`;
    44	}
    45	
    46	// Prompt-context view (fed back to agents): no cost footnotes, no raw error
    47	// dumps — keep the context agents reason over clean and a little smaller.
    48	function renderForContext(title: string, r: AgentResult): string {
    49	  if (r.ok) return `## ${title}\n\n${r.text}\n`;
    50	  return `## ${title}\n\n> (this participant produced no contribution this turn)\n`;
    51	}
    52	
    53	// git worktree add/remove on the same repo can contend on .git locks when run
    54	// concurrently — serialize the git operations (NOT the agent runs).
    55	let gitLock: Promise<unknown> = Promise.resolve();
    56	function withGitLock<T>(fn: () => Promise<T>): Promise<T> {
    57	  const p = gitLock.then(fn, fn);
    58	  gitLock = p.then(() => {}, () => {});
    59	  return p;
    60	}
    61	
    62	// Run a participant in ISOLATION. Isolation is a correctness requirement:
    63	// - Without repoPath: a throwaway temp dir, so agentic CLIs like agy cannot read
    64	//   sibling files — the contamination we caught in research/pre-m0-handrun.md.
    65	// - With repoPath: a DETACHED, THROWAWAY git worktree of HEAD — never the real
    66	//   checkout. Real-run lesson: evidence commands can write local runtime artifacts
    67	//   into the target repo. In a worktree those writes land in the disposable copy
    68	//   and die with it. Trade-off: agents see HEAD only (uncommitted changes are invisible) and
    69	//   untracked build artifacts (node_modules, …) are absent.
    70	export async function runIsolated(p: Participant, prompt: string, repoPath?: string): Promise<AgentResult> {
    71	  const dir = await mkdtemp(join(tmpdir(), "disputatio-"));
    72	  try {
    73	    if (!repoPath) return await p.run(prompt, dir);
    74	    const wt = join(dir, "wt");
    75	    await withGitLock(() => execFileAsync("git", ["-C", repoPath, "worktree", "add", "--detach", wt, "HEAD"]));
    76	    try {
    77	      return await p.run(prompt, wt);
    78	    } finally {
    79	      await withGitLock(async () => {
    80	        try { await execFileAsync("git", ["-C", repoPath, "worktree", "remove", "--force", wt]); }
    81	        catch { /* dir removal below + git's own prune cover the rest */ }
    82	      });
    83	    }
    84	  } finally {
    85	    await rm(dir, { recursive: true, force: true });
    86	  }
    87	}
    88	
    89	const proposePrompt = (task: string) =>
    90	  `You are one independent reviewer in a structured debate. The task:\n\n${task}\n\n` +
    91	  `Give your honest, concrete, opinionated proposal/answer. If a repository or files are present in your ` +
    92	  `working directory and relevant, READ them and run READ-ONLY commands (e.g. run the existing tests) to ` +
    93	  `ground your reasoning in real evidence. Respond in English, concise.`;
    94	
    95	const reactPrompt = (ctx: string, me: string) =>
    96	  `You are "${me}", one reviewer in a structured debate. The full debate so far:\n\n${ctx}\n\n` +
    97	  `React adversarially: where do you AGREE, where do you DISAGREE (find real, specific flaws), and what is ` +
    98	  `MISSING? State any objection you can back with EXECUTABLE EVIDENCE (run a test, check a file/API in your ` +
    99	  `working directory). Do not repeat what has already been said. Respond in English, concise.`;
   100	
   101	// Respondeo: the judge renders the consolidatio over the transcript ALONE (no repo
   102	// access, even in repo mode). It must ASK rather than guess — if a contested point
   103	// cannot be resolved from the transcript, it emits questions for the human instead of
   104	// fabricating a ruling. The mandatory first STATUS line is the machine signal index.ts
   105	// parses to surface NEEDS_INPUT.
   106	const respondeoPrompt = (ctx: string) =>
   107	  `You are the JUDGE (respondeo) closing a structured debate. The full transcript:\n\n${ctx}\n\n` +
   108	  `Render the consolidatio — the resolution. You reason over THIS TRANSCRIPT ALONE; you have no repository ` +
   109	  `access. Rules:\n` +
   110	  `1. Your FIRST line must be exactly one of: "STATUS: RESOLVED" or "STATUS: NEEDS_INPUT" (nothing else on it).\n` +
   111	  `2. Then record the SETTLED AGREEMENTS (what every participant converged on).\n` +
   112	  `3. Then rule on each CONTESTED point, weighing the arguments — prefer positions backed by executable ` +
   113	  `evidence over rhetoric.\n` +
   114	  `4. If — and only if — one or more contested points genuinely CANNOT be resolved from the transcript ` +
   115	  `without human input, use STATUS: NEEDS_INPUT, still record the settled agreements, then add a final ` +
   116	  `"## Quaestiones (for the human)" list of the specific questions, and issue NO ruling on those points. ` +
   117	  `Do not invent a verdict you cannot defend from the transcript.\n` +
   118	  `Respond in English, concise, in Markdown.`;
   119	
   120	// Only an explicit STATUS: NEEDS_INPUT on the first non-empty line triggers the human
   121	// path; anything else from a successful turn (RESOLVED or a missing/garbled marker)
   122	// is a verdict. A failed turn is classified FAILED by the caller. Exported because
   123	// --continue / --finalize parse a respondeo loaded back from disk (index.ts).
   124	export function parseRespondeoStatus(text: string): "RESOLVED" | "NEEDS_INPUT" {
   125	  const first = text.split("\n").map((l) => l.trim()).find((l) => l !== "") ?? "";
   126	  return /^STATUS:\s*NEEDS_INPUT\b/i.test(first) ? "NEEDS_INPUT" : "RESOLVED";
   127	}
   128	
   129	// Redactio — the SYNTHESIZER authors the actual deliverable the debate existed to
   130	// produce (the plan / review / proposal / outline the user will execute), NOT a
   131	// summary of who-said-what. This is the gap real use surfaced: respondeo.md holds the
   132	// RULING ON the debate, not the work-product born FROM it, so it lacks the data needed
   133	// to start the work. Transcript-only like respondeo: the debate already gathered the
   134	// evidence and it lives in the transcript (repo-grounded redactio is a follow-up).
   135	const finalizePrompt = (quaestio: string, transcript: string, determination: string) =>
   136	  `You are the SYNTHESIZER closing a structured debate. Author the FINAL DELIVERABLE the ` +
   137	  `debate existed to produce — the document a human or agent will use to START THE WORK ` +
   138	  `(implement, review, present, propose). This is the product, NOT minutes of the debate.\n\n` +
   139	  `The original quaestio (it fixes the deliverable's PURPOSE and shape):\n\n${quaestio}\n\n` +
   140	  `The full debate transcript (proposals, reactions, evidence):\n\n${transcript}\n\n` +
   141	  `The respondeo — the judge's determination (what was settled, what was ruled, and why):\n\n${determination}\n\n` +
   142	  `Rules:\n` +
   143	  `1. Infer the deliverable TYPE from the quaestio (implementation plan, code-review report, ` +
   144	  `proposal, presentation outline, …) and produce THAT artifact, in its natural shape.\n` +
   145	  `2. Build it from the SETTLED decisions in the respondeo: adopt what won, drop what was ` +
   146	  `rejected, and fold in the evidence that backed the winning positions.\n` +
   147	  `3. If a repository is present in your working directory, READ it and run READ-ONLY ` +
   148	  `commands to ground the deliverable in the REAL files — prefer concrete, file-accurate ` +
   149	  `steps (real paths, real current shapes) over generic ones. (No repo present = work from ` +
   150	  `the transcript alone.)\n` +
   151	  `4. Make it SELF-CONTAINED: someone reading ONLY this document must have everything needed ` +
   152	  `to begin — restate the context and decisions; never say "as discussed above".\n` +
   153	  `5. Leave the debate's blow-by-blow OUT; keep a rationale only where it is load-bearing for execution.\n` +
   154	  `6. If the respondeo left points unresolved, end with a short "## Open points" section so they ` +
   155	  `are not lost — but do not block the deliverable on them.\n` +
   156	  `Respond in English, in Markdown.`;
   157	
   158	// Continuation (--continue): the human has answered the respondeo's open questions.
   159	// Re-invoke the JUDGE ALONE (the cheap path) with the transcript + prior determination
   160	// + the answers. If the answers merely DISAMBIGUATE points the debaters already argued,
   161	// the judge can now rule (RESOLVED). If they open genuinely NEW ground nobody argued,
   162	// the judge must NOT invent a verdict — it returns NEEDS_INPUT again, which is the
   163	// signal that a fresh reaction round is needed (re-debate is the documented follow-up).
   164	const continuePrompt = (quaestio: string, transcript: string, previousDetermination: string, humanAnswers: string) =>
   165	  `You are the JUDGE (respondeo) RESUMING a structured debate you previously could not fully ` +
   166	  `resolve. You reason over the TRANSCRIPT and your PRIOR determination ALONE — no repository ` +
   167	  `access. The human has now answered your open questions.\n\n` +
   168	  `The original quaestio:\n\n${quaestio}\n\n` +
   169	  `The full debate transcript:\n\n${transcript}\n\n` +
   170	  `Your PRIOR determination (it ended in NEEDS_INPUT):\n\n${previousDetermination}\n\n` +
   171	  `The human's answers to your open questions:\n\n${humanAnswers}\n\n` +
   172	  `Rules:\n` +
   173	  `1. Your FIRST line must be exactly one of: "STATUS: RESOLVED" or "STATUS: NEEDS_INPUT".\n` +
   174	  `2. Resolve every point you previously left open, USING the human's answers. Do not re-ask ` +
   175	  `what they have already answered.\n` +
   176	  `3. Carry forward the settled agreements and prior rulings that still hold.\n` +
   177	  `4. ONLY if the answers open a genuinely NEW question the debaters never argued, which you ` +
   178	  `cannot settle from the transcript without inventing a verdict, use STATUS: NEEDS_INPUT, ` +
   179	  `record what is now settled, and list ONLY the new "## Quaestiones (for the human)". ` +
   180	  `Do not fabricate a verdict you cannot defend from the transcript.\n` +
   181	  `Respond in English, concise, in Markdown.`;
   182	
   183	// The redactio turn: author the deliverable from a RESOLVED determination. UNLIKE the
   184	// respondeo (which is transcript-only by invariant — it must ASK, not guess), the
   185	// synthesizer MAY be repo-grounded: with repoPath it runs in a read-only throwaway
   186	// worktree of HEAD, so the deliverable can cite real files and current shapes. Exported
   187	// so --continue / --finalize can reuse it standalone over a saved debate.
   188	export async function runFinalize(
   189	  judge: Participant, quaestio: string, transcript: string, determination: string, repoPath?: string,
   190	): Promise<Turn> {
   191	  const r = await runIsolated(judge, finalizePrompt(quaestio, transcript, determination), repoPath);
   192	  return { title: `Final report — ${judge.display}`, participant: judge.id, result: r };
   193	}
   194	
   195	// The continuation turn: re-judge after the human answered. Transcript-only, like respondeo.
   196	export async function runContinuation(
   197	  judge: Participant, quaestio: string, transcript: string, previousDetermination: string, humanAnswers: string,
   198	): Promise<Turn> {
   199	  const r = await runIsolated(judge, continuePrompt(quaestio, transcript, previousDetermination, humanAnswers));
   200	  return { title: `Respondeo (continued) — ${judge.display}`, participant: judge.id, result: r };
   201	}
   202	
   203	export async function runDebate(
   204	  task: string,
   205	  participants: Participant[],
   206	  rounds: number,
   207	  repoPath?: string,
   208	  judge?: Participant,
   209	): Promise<DebateOutcome> {
   210	  const header = `# Disputatio debate\n\n## Task\n\n${task}\n`;
   211	  const fileParts: string[] = [header];
   212	  const ctxParts: string[] = [header];
   213	  const turns: Turn[] = [];
   214	
   215	  const record = (title: string, p: Participant, r: AgentResult) => {
   216	    turns.push({ title, participant: p.id, result: r });
   217	    fileParts.push(render(title, r));
   218	    ctxParts.push(renderForContext(title, r));
   219	  };
   220	
   221	  // Round 1 — independent proposals (parallel; each isolated so they don't peek).
   222	  log(`Round 1 — independent proposals: ${participants.map((p) => p.id).join(", ")}`);
   223	  const proposals = await Promise.all(
   224	    participants.map(async (p) => ({ p, r: await runIsolated(p, proposePrompt(task), repoPath) })),
   225	  );
   226	  for (const { p, r } of proposals) record(`Proposal — ${p.display}`, p, r);
   227	
   228	  // A debate needs at least two voices. Fewer than 2 successful proposals means
   229	  // the surviving agent would "debate" a monologue — abort loudly instead of
   230	  // producing a plausible-looking but worthless artifact (real-run lesson, 2026-06-11).
   231	  const okProposals = proposals.filter(({ r }) => r.ok).length;
   232	  if (okProposals < 2) {
   233	    const failures = proposals
   234	      .filter(({ r }) => !r.ok)
   235	      .map(({ p, r }) => `${p.id}: ${(r as { error: string }).error}`)
   236	      .join(" | ");
   237	    const aborted = `only ${okProposals}/${participants.length} proposals succeeded — no debate possible. Failures: ${failures}`;
   238	    log(`ABORTED — ${aborted}`);
   239	    fileParts.push(`## Debate aborted\n\n> ⚠️ ${aborted}\n`);
   240	    return { transcript: fileParts.join("\n"), turns, aborted };
   241	  }
   242	
   243	  // Reaction rounds — each participant reacts to the full transcript snapshot.
   244	  for (let round = 1; round <= rounds; round++) {
   245	    log(`Round ${round + 1} — reactions`);
   246	    const ctx = ctxParts.join("\n");
   247	    const reactions = await Promise.all(
   248	      participants.map(async (p) => ({ p, r: await runIsolated(p, reactPrompt(ctx, p.display), repoPath) })),
   249	    );
   250	    for (const { p, r } of reactions) record(`Round ${round} reaction — ${p.display}`, p, r);
   251	  }
   252	
   253	  // Respondeo — opt-in judge turn (transcript-only: no repoPath, even in repo mode).
   254	  // A failed judge is non-fatal: it's recorded, but the debate itself still succeeded.
   255	  let respondeo: DebateOutcome["respondeo"];
   256	  let finalReport: DebateOutcome["finalReport"];
   257	  let finalReportError: DebateOutcome["finalReportError"];
   258	  if (judge) {
   259	    const debateCtx = ctxParts.join("\n"); // clean transcript snapshot BEFORE the respondeo turn
   260	    log(`Respondeo — ${judge.display} renders the consolidatio`);
   261	    const r = await runIsolated(judge, respondeoPrompt(debateCtx));
   262	    record(`Respondeo — ${judge.display}`, judge, r);
   263	    respondeo = r.ok
   264	      ? { status: parseRespondeoStatus(r.text), text: r.text }
   265	      : { status: "FAILED", text: `Respondeo turn failed: ${r.error}` };
   266	
   267	    // Redactio — author the deliverable, but ONLY when the respondeo actually RESOLVED.
   268	    // On NEEDS_INPUT the deliverable waits for the human (--continue); on FAILED there
   269	    // is nothing to synthesize. The determination is passed separately, so finalize sees
   270	    // the clean debate transcript (not the respondeo turn re-appended). A failed redactio
   271	    // is non-fatal — it's recorded, but the debate + verdict still succeeded.
   272	    if (respondeo.status === "RESOLVED") {
   273	      log(`Redactio — ${judge.display} drafts the final deliverable`);
   274	      // Repo-grounded when the debate ran with --repo: the deliverable cites real files.
   275	      const turn = await runFinalize(judge, task, debateCtx, respondeo.text, repoPath);
   276	      turns.push(turn);
   277	      fileParts.push(render(turn.title, turn.result));
   278	      if (turn.result.ok) {
   279	        finalReport = { text: turn.result.text };
   280	      } else {
   281	        finalReportError = { budgetExhausted: turn.result.budgetExhausted === true, message: turn.result.error };
   282	      }
   283	    }
   284	  }
   285	
   286	  return { transcript: fileParts.join("\n"), turns, respondeo, finalReport, finalReportError };
   287	}
"}}

